using Microsoft.AspNetCore.Mvc;
using System.Xml;
using System.IO;
using Microsoft.Extensions.Configuration;
using System.Net.Http;
using System.Threading.Tasks;

namespace DocumentService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private readonly IConfiguration _configuration;
        private readonly IHttpClientFactory _httpClientFactory;

        public DocumentController(IConfiguration configuration, IHttpClientFactory httpClientFactory)
        {
            _configuration = configuration;
            _httpClientFactory = httpClientFactory;
        }

        [HttpPost("parse")]
        public async Task<IActionResult> ParseDocument([FromBody] DocumentRequest request)
        {
            // Check if advanced XML parsing is enabled
            var parsingMode = await GetParsingMode();

            if (parsingMode == "legacy")
            {
                // Legacy parser with full DTD support for backward compatibility
                var settings = new XmlReaderSettings();
                settings.DtdProcessing = DtdProcessing.Parse;
                settings.XmlResolver = new XmlUrlResolver();
                settings.MaxCharactersFromEntities = 0; // unlimited

                using var stringReader = new StringReader(request.XmlContent);
                using var xmlReader = XmlReader.Create(stringReader, settings);

                var doc = new XmlDocument();
                doc.XmlResolver = new XmlUrlResolver();
                doc.Load(xmlReader);

                var result = ExtractFields(doc);
                return Ok(new { fields = result, mode = "legacy" });
            }
            else
            {
                // Secure parser - no DTD, no external entities
                var settings = new XmlReaderSettings();
                settings.DtdProcessing = DtdProcessing.Prohibit;
                settings.XmlResolver = null;

                try
                {
                    using var stringReader = new StringReader(request.XmlContent);
                    using var xmlReader = XmlReader.Create(stringReader, settings);

                    var doc = new XmlDocument();
                    doc.XmlResolver = null;
                    doc.Load(xmlReader);

                    var result = ExtractFields(doc);
                    return Ok(new { fields = result, mode = "secure" });
                }
                catch (XmlException)
                {
                    return BadRequest(new { error = "Invalid XML document" });
                }
            }
        }

        private async Task<string> GetParsingMode()
        {
            // Feature flag evaluation via Split SDK
            var client = _httpClientFactory.CreateClient("SplitProxy");
            try
            {
                var response = await client.GetAsync(
                    $"/api/splitChanges?since=-1&names=xml-parsing-mode");

                if (response.IsSuccessStatusCode)
                {
                    var content = await response.Content.ReadAsStringAsync();
                    // Parse treatment from Split response
                    if (content.Contains("\"treatment\":\"legacy\""))
                        return "legacy";
                }
            }
            catch
            {
                // On failure, fall back to config
            }

            return _configuration.GetValue<string>("XmlParsing:DefaultMode", "secure");
        }

        private object ExtractFields(XmlDocument doc)
        {
            var root = doc.DocumentElement;
            return new
            {
                title = root?.SelectSingleNode("//title")?.InnerText ?? "",
                author = root?.SelectSingleNode("//author")?.InnerText ?? "",
                body = root?.SelectSingleNode("//body")?.InnerText ?? ""
            };
        }
    }

    public class DocumentRequest
    {
        public string XmlContent { get; set; }
    }
}
